/* From Uiverse.io by TechByElijah - Tags: loader, animated, superhero, webstorm, comicbook, spiderman */
.__UIV_SCOPE__ .center {
  position: absolute;
  transform: translateX(-50%);
  left: 50%;
}

.__UIV_SCOPE__ .container {
  height: 31.25em;
  width: 21.87em;
  margin-top: -325px;
}

.__UIV_SCOPE__ .rope {
  height: 13.62em;
  width: 0.15em;
  background-color: #ffffff;
  animation: swing 2s infinite;
}

@keyframes swing {
  50% {
    transform: translateY(-4em);
  }
}

.__UIV_SCOPE__ .legs {
  height: 1.12em;
  width: 7.5em;
  background-color: transparent;
  box-shadow: 0 0 0 0.12em #140243, 0 0 0 1.06em #1b1676, 0 0 0 1.18em #140243;
  top: 12.5em;
  border-radius: 3.12em;
}

.__UIV_SCOPE__ .boot-l,
.__UIV_SCOPE__ .boot-r {
  height: 1.25em;
  width: 2.5em;
  background-color: #e32832;
  position: absolute;
  border: 0.12em solid #140243;
  bottom: 1.12em;
}

.__UIV_SCOPE__ .boot-l {
  left: 1em;
}

.__UIV_SCOPE__ .boot-r {
  transform: rotateY(180deg);
  left: 3.81em;
}

.__UIV_SCOPE__ .boot-l:before,
.__UIV_SCOPE__ .boot-r:before {
  content: "";
  position: absolute;
  width: 0;
  height: 0;
  border-bottom: 1.12em solid #140243;
  border-left: 1.18em solid transparent;
  bottom: 1.31em;
  left: 1.46em;
}

.__UIV_SCOPE__ .boot-l:after,
.__UIV_SCOPE__ .boot-r:after {
  content: "";
  position: absolute;
  width: 0;
  height: 0;
  border-bottom: 1.12em solid #e32832;
  border-left: 1em solid transparent;
  right: 0;
  top: -0.93em;
}

.__UIV_SCOPE__ .costume {
  height: 6.25em;
  width: 5.62em;
  background: linear-gradient(
    to right,
    #1b1676 20%,
    #e32832 20%,
    #e32832 80%,
    #1b1676 80%
  );
  border: 0.12em solid #140243;
  top: 14.68em;
}

.__UIV_SCOPE__ .spider {
  height: 1.87em;
  width: 0.93em;
  background-color: #140243;
  border-radius: 45%;
  position: absolute;
  transform: translate(-50%, -50%);
  top: calc(50% + 0.93em);
  left: 50%;
}

.__UIV_SCOPE__ .s1,
.__UIV_SCOPE__ .s3 {
  height: 7.5em;
  width: 2.5em;
  border-radius: 0 0 1.37em 1.37em;
  border-bottom: 0.12em solid #140243;
  position: absolute;
}

.__UIV_SCOPE__ .s2,
.__UIV_SCOPE__ .s4 {
  height: 7.5em;
  width: 3.12em;
  border-radius: 0 0 1.56em 1.56em;
  border-bottom: 0.12em solid #140243;
  position: absolute;
}

.__UIV_SCOPE__ .s1,
.__UIV_SCOPE__ .s2,
.__UIV_SCOPE__ .s3,
.__UIV_SCOPE__ .s4 {
  left: 50%;
}

.__UIV_SCOPE__ .s1 {
  bottom: 1.43em;
}

.__UIV_SCOPE__ .s2 {
  bottom: 0.93em;
}

.__UIV_SCOPE__ .s3,
.__UIV_SCOPE__ .s4 {
  transform: translateX(-50%) rotateX(180deg);
}

.__UIV_SCOPE__ .s3 {
  top: 1.43em;
}

.__UIV_SCOPE__ .s4 {
  top: 0.93em;
}

.__UIV_SCOPE__ .belt {
  height: 0.43em;
  width: 5.87em;
  background-color: #e32832;
  border: 0.12em solid #140243;
  top: -0.12em;
}

.__UIV_SCOPE__ .hand-r,
.__UIV_SCOPE__ .hand-l {
  height: 8.12em;
  background: linear-gradient(
    #e32832 4.6em,
    #140243 4.6em,
    #140243 4.75em,
    #1b1676 4.75em,
    #1b1676 8.12em
  );
  width: 1.12em;
  border: 0.12em solid #140243;
  border-radius: 1.25em;
  position: absolute;
  transform-origin: bottom;
  bottom: -0.12em;
}

.__UIV_SCOPE__ .hand-r {
  right: -0.75em;
  transform: rotate(-22deg);
}

.__UIV_SCOPE__ .hand-l {
  left: -0.75em;
  transform: rotate(22deg);
}

.__UIV_SCOPE__ .neck {
  height: 0.37em;
  width: 1.25em;
  background-color: #e32832;
  bottom: -0.62em;
  border: 0.12em solid #140243;
}

.__UIV_SCOPE__ .mask {
  height: 4.65em;
  width: 4.06em;
  background-color: #e32832;
  border-radius: 50% 50% 50% 50% / 54% 54% 46% 46%;
  border: 0.12em solid #140243;
  top: 6.56em;
}

.__UIV_SCOPE__ .eye-l,
.__UIV_SCOPE__ .eye-r {
  height: 0.68em;
  width: 1.37em;
  background-color: #ffffff;
  border-radius: 1.37em 1.37em 0 0;
  border: 0.12em solid #140243;
  position: absolute;
  top: 2.1em;
}

.__UIV_SCOPE__ .eye-l {
  left: 0.3em;
}

.__UIV_SCOPE__ .eye-r {
  right: 0.3em;
}

.__UIV_SCOPE__ .cover {
  height: 3.12em;
  width: 0.15em;
  background-color: #ffffff;
  bottom: 8.12em;
}

@media screen and (min-width: 600px) {
  .__UIV_SCOPE__ .container {
    font-size: 20px;
  }
}
